<template><view class="page"><view class="top"><text class="title">我的笔记</text><text class="sub">收集、整理，慢慢长成自己的知识库</text></view><view class="search" @click="search">⌕　搜索我的笔记</view><scroll-view scroll-x class="tabs"><text v-for="c in categories" :key="c" :class="['tab',{active:current===c}]" @click="current=c">{{c}}</text></scroll-view><view class="count">{{filtered.length}} 条笔记 <text @click="create">＋ 新建</text></view><view class="card" v-for="n in filtered" :key="n._id" @click="detail(n._id)"><view class="card-head"><text class="tag">{{n.category}}</text><text class="time">{{n.updatedAt}}</text></view><text class="name">{{n.title}}</text><text class="desc">{{n.summary}}</text><view class="foot"><text>{{n.tags.map(t=>'#'+t).join('　')}}</text><text>···</text></view></view><view class="ai" @click="ai">✧　AI 灵感工具　<text>整理 · 润色 · 思维导图</text>　›</view></view></template>
<script setup>
import { computed,ref } from 'vue';import {notes,categories} from '../../src/data/demo.js';const current=ref('全部');const filtered=computed(()=>current.value==='全部'?notes:notes.filter(n=>n.category===current.value));function create(){uni.navigateTo({url:'/pages/editor/editor'})}function detail(id){uni.navigateTo({url:'/pages/detail/detail?id='+id})}function search(){uni.showToast({title:'搜索功能待接入',icon:'none'})}function ai(){uni.showToast({title:'AI 功能预留中',icon:'none'})}
</script>
<style scoped>
.page{padding:24px 20px}.top{margin:8px 0 20px}.title{display:block;font-size:25px;font-weight:700}.sub{display:block;margin-top:8px;font-size:12px;color:#9298a1}.search{padding:13px 15px;border-radius:13px;background:#fff;color:#a0a5ad;font-size:13px}.tabs{white-space:nowrap;margin:19px -20px 0;padding:0 20px}.tab{display:inline-block;padding:8px 13px;margin-right:6px;border-radius:18px;color:#7f8590;font-size:12px}.tab.active{background:#536cf1;color:white}.count{display:flex;justify-content:space-between;margin:20px 0 9px;font-size:12px;color:#858b95}.count text{color:#536cf1}.card{padding:16px;margin-top:10px;background:#fff;border-radius:16px}.card-head,.foot{display:flex;justify-content:space-between}.tag{font-size:10px;color:#536cf1;background:#eef0ff;padding:5px 8px;border-radius:8px}.time{font-size:10px;color:#a3a7ae}.name{display:block;margin-top:13px;font-weight:700;font-size:16px}.desc{display:block;margin-top:8px;color:#777e88;font-size:12px;line-height:1.7}.foot{margin-top:14px;color:#9a9faa;font-size:10px}.ai{margin-top:18px;padding:15px;background:#ecefff;border-radius:14px;color:#536cf1;font-size:13px}.ai text{color:#8289a3;font-size:10px}
</style>
